-- =====================================================================
-- VIEW: Pre-visit snapshot for the doctor (core goal of the project)
-- One row per appointment: today's symptoms + allergies + ongoing
-- medicines + active conditions + latest summary.
-- =====================================================================

CREATE OR REPLACE VIEW v_previsit_snapshot AS
SELECT
    a.appointment_id,
    a.appointment_date,
    a.time_slot,
    a.doctor_id,
    a.patient_id,
    pp.full_name                                                  AS patient_name,
    a.reason,
    a.pre_visit_notes,
    (SELECT GROUP_CONCAT(CONCAT(s.symptom_name, IF(s.severity IS NULL, '', CONCAT(' (', s.severity, ')')))
                         SEPARATOR ', ')
       FROM appointment_symptom s WHERE s.appointment_id = a.appointment_id)      AS todays_symptoms,
    (SELECT GROUP_CONCAT(CONCAT(al.allergen, IF(al.severity IS NULL, '', CONCAT(' (', al.severity, ')')))
                         SEPARATOR ', ')
       FROM allergy al WHERE al.patient_id = a.patient_id AND al.status = 'Active') AS active_allergies,
    (SELECT GROUP_CONCAT(pc.condition_name SEPARATOR ', ')
       FROM patient_condition pc
      WHERE pc.patient_id = a.patient_id AND pc.status IN ('Active','Controlled')) AS active_conditions,
    (SELECT GROUP_CONCAT(CONCAT(pi.medicine_name, ' ', IFNULL(pi.dosage,'')) SEPARATOR ', ')
       FROM prescription pr
       JOIN prescription_item pi ON pi.prescription_id = pr.prescription_id
      WHERE pr.patient_id = a.patient_id AND pi.is_ongoing = TRUE)                 AS ongoing_medicines,
    (SELECT ms.summary_text FROM medical_summary ms
      WHERE ms.patient_id = a.patient_id AND ms.is_current = TRUE
      ORDER BY ms.generated_at DESC LIMIT 1)                                       AS latest_summary
FROM appointment a
JOIN patient_profile pt ON pt.patient_id = a.patient_id
JOIN person pp          ON pp.person_id  = pt.person_id;

-- Example usage:
--   SELECT * FROM v_previsit_snapshot
--   WHERE doctor_id = 1 AND appointment_date = CURDATE();